--
-- Table structure for table `ERP_finance_expenses`
--

DROP TABLE IF EXISTS `ERP_finance_expenses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ERP_finance_expenses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `concept` varchar(255) NOT NULL,
  `category` varchar(255) NOT NULL,
  `referenceId` int(11) DEFAULT NULL,
  `referenceType` varchar(255) DEFAULT NULL,
  `status` enum('pending','paid') NOT NULL DEFAULT 'paid',
  `counterpartyName` varchar(255) DEFAULT NULL,
  `createdBy` int(11) NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `referenceId` (`referenceId`),
  KEY `createdBy` (`createdBy`),
  CONSTRAINT `ERP_finance_expenses_ibfk_1` FOREIGN KEY (`referenceId`) REFERENCES `ERP_inventory_products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ERP_finance_expenses_ibfk_2` FOREIGN KEY (`createdBy`) REFERENCES `accounts` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=534 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

