--
-- Table structure for table `ERP_inventory_products`
--

DROP TABLE IF EXISTS `ERP_inventory_products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ERP_inventory_products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `desc` text DEFAULT NULL,
  `type` enum('raw','intermediate','final') NOT NULL DEFAULT 'raw',
  `unitId` int(11) NOT NULL,
  `categoryId` int(11) DEFAULT NULL,
  `standardWeightGrams` float DEFAULT 0,
  `netWeight` float DEFAULT 0,
  `stock` float DEFAULT 0,
  `minStock` float DEFAULT 0,
  `price` decimal(10,2) DEFAULT 0.00,
  `wholesaleRules` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`wholesaleRules`)),
  `distributorPrice` decimal(10,2) DEFAULT 0.00,
  `taxRate` decimal(5,2) DEFAULT 0.00,
  `sku` varchar(64) DEFAULT NULL,
  `barcode` varchar(64) DEFAULT NULL,
  `isActive` tinyint(1) DEFAULT 1,
  `primaryImageUrl` varchar(500) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sku` (`sku`),
  UNIQUE KEY `barcode` (`barcode`),
  UNIQUE KEY `e_r_p_inventory_products_sku` (`sku`),
  KEY `unitId` (`unitId`),
  KEY `e_r_p_inventory_products_category_id` (`categoryId`),
  KEY `e_r_p_inventory_products_type` (`type`),
  KEY `e_r_p_inventory_products_is_active` (`isActive`),
  CONSTRAINT `ERP_inventory_products_ibfk_1` FOREIGN KEY (`unitId`) REFERENCES `ERP_inventory_units` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `ERP_inventory_products_ibfk_2` FOREIGN KEY (`categoryId`) REFERENCES `ERP_inventory_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

