DROP TABLE IF EXISTS `ERP_order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ERP_order_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `orderId` int(11) NOT NULL,
  `productId` int(11) NOT NULL,
  `quantity` float NOT NULL,
  `price` float NOT NULL,
  `soldQty` float NOT NULL DEFAULT 0 COMMENT 'Cantidad realmente vendida (cobrable)',
  `damagedQty` float NOT NULL DEFAULT 0 COMMENT 'Cantidad dañada / merma',
  `giftQty` float NOT NULL DEFAULT 0 COMMENT 'Cantidad entregada como yapa',
  `replacedQty` float NOT NULL DEFAULT 0 COMMENT 'Cantidad entregada como reemplazo',
  `deliveredAt` datetime DEFAULT NULL,
  `paidAt` datetime DEFAULT NULL COMMENT 'Fecha cuando quedó totalmente pagado (último pago)',
  PRIMARY KEY (`id`),
