DROP TABLE IF EXISTS `ERP_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ERP_orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customerId` int(11) NOT NULL,
  `status` enum('pendiente','entregado','pagado') DEFAULT 'pendiente',
  `notes` text DEFAULT NULL,
  `shiftId` int(11) DEFAULT NULL,
  `paymentMethod` varchar(40) DEFAULT NULL,
  `paidAt` datetime DEFAULT NULL,
  `documentType` varchar(30) DEFAULT NULL COMMENT 'factura | nota_venta | documento | consumidor_final',
  `date` datetime NOT NULL,
  `financeIncomeId` int(11) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `customerId` (`customerId`),
  KEY `shiftId` (`shiftId`),
  CONSTRAINT `ERP_orders_ibfk_3` FOREIGN KEY (`customerId`) REFERENCES `ERP_customers` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ERP_orders_ibfk_4` FOREIGN KEY (`shiftId`) REFERENCES `ERP_cash_shifts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=688 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

